qwords = lambda q: len(re.findall(r"\S+", q))
out = []
problems = []
for c in CELLS:
    v = by[c['key']]
    q = v['quote']
    n = qwords(q)
    if not (10 <= n <= 30): problems.append((c['key'],'words',n))
    if not re.search(r'\d', c['statement']): problems.append((c['key'],'no-digit',0))
    if not v.get('quote_in_source'): problems.append((c['key'],'quote',0))
    cell = {
      'atom': 'DIP27-'+c['key'],
      'statement': c['statement'],
      'domain': 'evolution.ecology',
      'kind': c['kind'],
      'mechanism': c['mechanism'],
      'formula': None,
      'symbols': c['symbols'],
      'conditions': c['conditions'],
      'works': [{'doi': v['doi'], 'locator': v['locator'], 'access': 'abstract' if v['doi']!='10.3389/fnmol.2017.00101' else 'fragment', 'quote': q}],
      'confidence': 'medium',
      'locator_status': 'verified',
      'tags': c['tags'],
      'notes': c['notes'],
    }
    out.append(cell)
    print('DIP27-'+c['key'], '| words', n, '|', v['doi'], '|', v['year'], '|', v['title'][:60])
print('PROBLEMS:', problems)
open('/root/marfagenez/literature/dips/reports/dip-2026-11-23-27.jsonl','w',encoding='utf-8').write('\n'.join(json.dumps(x, ensure_ascii=False) for x in out)+'\n')
print('written', len(out), 'cells')
